// The public shape Vercel's CLI installs into its fetch wrapper when proxy
// environment variables are present. The methods deliberately throw: scriptc's
// native transport must recognize this adapter without calling through it.
export class EnvProxyDispatcher {
  constructor() {
    this.noProxyValue = "";
    this.noProxyEntries = [];
    this.directAgent = {};
    this.httpAgent = {};
    this.httpsAgent = {};
  }

  dispatch() {
    throw new Error("the native transport must not invoke the dispatcher");
  }

  close() {}
  destroy() {}
  agents() {}
  getAgent() {}
  shouldProxy() {}
  parseNoProxy() {}
}
